import React, { useState } from "react";
import pitterImage from "../images/pitter.png";
import heartIcon from "../icons/favorite_border.svg";
import locationIcon from "../icons/location_on.svg";
import "./petCard.css";

export default function petCard() {
  const [isFavorite, setIsFavorite] = useState(false);

  return (
    <div className="card">
      <img src={pitterImage} alt="Pitter" className="card-image" />
      <div className="card-content">
        <div className="card-header">
          <h2 className="card-title">Pitter</h2>
          <img 
            src={heartIcon} 
            alt="Heart" 
            className={`heart-icon ${isFavorite ? "favorite" : ""}`} 
            onClick={() => setIsFavorite(!isFavorite)}
          />
        </div>
        <p className="location">
          <img src={locationIcon} alt="Location" className="location-icon" />
          California, USA
        </p>
        <div className="info-grid">
          <p><span>Gender:</span> <span className="tag">Male</span></p>
          <p><span>Breed:</span> <span className="tag">Pit Bull</span></p>
          <p><span>Age:</span> <span className="tag">5 years</span></p>
          <p><span>Size:</span> <span className="tag">Large</span></p>
        </div>
        <p className="description">
          Pitter is a friendly, playful, smart male dog. Only adopted to a ho...
        </p>
        <button className="more-info">More Info</button>
      </div>
    </div>
  );
}
